/* JS Design System v0.8 · .field · 토큰(var(--*))은 assets/style.css :root 참고 */
.field{display:flex;flex-direction:column;gap:0.375rem;min-width:16.25rem;font-size:var(--font-size-14);line-height:1.6}
.field label:where(:not(.checkbox):not(.radio)){font-weight:600}
.field label em{color:var(--foreground-negative-strong);font-style:normal;margin-left:2px}
.field input:where(:not([type=checkbox]):not([type=radio]):not([type=range])),.field textarea{height:2.5rem;border:1px solid var(--line-neutral-primary);border-radius:var(--radius-md);padding:0 0.875rem;font:inherit;font-size:var(--font-size-14);background:var(--surface-elevated-primary);color:var(--foreground-neutral-primary);width:100%;transition:border-color var(--motion-fast),box-shadow var(--motion-fast)}
.field textarea{height:auto;min-height:6rem;padding:0.625rem 0.875rem;resize:vertical;line-height:1.5}
.field input::placeholder,.field textarea::placeholder{color:var(--foreground-neutral-tertiary)}
.field input:where(:not([type=checkbox]):not([type=radio]):not([type=range])):hover,.field textarea:hover{border-color:var(--line-neutral-primary)}
.field input:where(:not([type=checkbox]):not([type=radio]):not([type=range])):focus,.field textarea:focus-within{border-color:var(--foreground-brand-primary);box-shadow:0 0 0 4px var(--line-brand-focus);outline:none}
.field input:where(:not([type=checkbox]):not([type=radio]):not([type=range])):disabled,.field textarea:disabled{background:var(--surface-disable-primary);color:var(--foreground-disable-primary);cursor:not-allowed}
.field input:where(:not([type=checkbox]):not([type=radio]):not([type=range])):read-only:not(:disabled){background:var(--background-neutral-secondary)}
.field .help{color:var(--foreground-neutral-tertiary);font-size:var(--font-size-12);contain:inline-size;word-break:keep-all;overflow-wrap:anywhere}
.field.error input:where(:not([type=checkbox]):not([type=radio]):not([type=range])),.field.error textarea,.field.error .affix{border-color:var(--foreground-negative-primary)}
