import { Checkbox } from "@jiran/ds-react";

export default function Example() {
  return <Checkbox>정책 배포 시 알림</Checkbox>;
}

import { Checkbox } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Checkbox>Unchecked</Checkbox>
      <Checkbox defaultChecked>Checked</Checkbox>
      <Checkbox indeterminate>Indeterminate</Checkbox>
      <Checkbox disabled>Disabled</Checkbox>
      <Checkbox defaultChecked disabled>Disabled checked</Checkbox>
    </>
  );
}

import { Checkbox, CheckboxGroup } from "@jiran/ds-react";

export default function Example() {
  return (
    <CheckboxGroup>
      <Checkbox defaultChecked description="배포가 완료되면 관리자 메일로 알립니다">정책 배포 시 알림</Checkbox>
      <Checkbox description="매주 월요일 09:00 에 발송">주간 리포트 수신</Checkbox>
    </CheckboxGroup>
  );
}

import { useState } from "react";
import { Checkbox, CheckboxGroup } from "@jiran/ds-react";

const LEVELS = ["Critical", "High", "Medium", "Low", "Info"];

export default function Example() {
  const [sel, setSel] = useState<string[]>(["Critical", "High"]);
  const all = sel.length === LEVELS.length, some = sel.length > 0 && !all;
  return (
    <CheckboxGroup>
      <Checkbox checked={all} indeterminate={some} onChange={(on) => setSel(on ? LEVELS : [])}>
        <b>전체 선택</b>
      </Checkbox>
      <CheckboxGroup row style={{ paddingLeft: 24 }}>
        {LEVELS.map((l) => (
          <Checkbox key={l} checked={sel.includes(l)} onChange={(on) => setSel((s) => (on ? [...s, l] : s.filter((x) => x !== l)))}>
            {l}
          </Checkbox>
        ))}
      </CheckboxGroup>
    </CheckboxGroup>
  );
}

import { Button, Checkbox, CheckboxGroup, Form, FormActions, FormLegend } from "@jiran/ds-react";

export default function Example() {
  return (
    <Form validate style={{ width: 360 }} onSubmit={(e) => e.preventDefault()}>
      <FormLegend />
      <CheckboxGroup legend="알림 채널" required help="하나 이상 선택합니다.">
        <Checkbox>이메일</Checkbox>
        <Checkbox>SMS</Checkbox>
        <Checkbox>콘솔 알림</Checkbox>
      </CheckboxGroup>
      <FormActions>
        <Button type="submit">저장</Button>
      </FormActions>
    </Form>
  );
}

