import { Chip } from "@jiran/ds-react";

export default function Example() {
  return <Chip>Critical</Chip>;
}

import { useState } from "react";
import { Chip, ChipGroup } from "@jiran/ds-react";

const LEVELS = ["Critical", "High", "Medium", "Low", "Info"];

export default function Example() {
  const [sel, setSel] = useState(["Critical", "High"]);
  return (
    <ChipGroup clearable={sel.length > 0} onClear={() => setSel([])}>
      {LEVELS.map((l) => (
        <Chip key={l} selected={sel.includes(l)} onSelectedChange={(on) => setSel((s) => (on ? [...s, l] : s.filter((x) => x !== l)))}>{l}</Chip>
      ))}
    </ChipGroup>
  );
}

import { useState } from "react";
import { Chip, ChipGroup } from "@jiran/ds-react";

export default function Example() {
  const [ips, setIps] = useState(["10.0.0.12", "10.0.0.13", "192.168.1.0/24"]);
  return (
    <ChipGroup>
      {ips.map((ip) => (
        <Chip key={ip} onRemove={() => setIps((s) => s.filter((x) => x !== ip))}>{ip}</Chip>
      ))}
      <Chip action icon="plus" onClick={() => setIps((s) => [...s, `10.0.0.${20 + s.length}`])}>추가</Chip>
    </ChipGroup>
  );
}

import { Chip } from "@jiran/ds-react";

export default function Example() {
  return (
    <>
      <Chip size="sm" defaultSelected>Small</Chip>
      <Chip defaultSelected>Default</Chip>
      <Chip disabled>Disabled</Chip>
      <Chip disabled onRemove={() => {}}>10.0.0.12</Chip>
    </>
  );
}

import { useState } from "react";
import { Chip, ChipGroup } from "@jiran/ds-react";

export default function Example() {
  const [mails, setMails] = useState(["security-audit-notification@corp.example.com", "admin@example.com"]);
  return (
    <ChipGroup>
      {mails.map((m) => (
        <Chip key={m} onRemove={() => setMails((s) => s.filter((x) => x !== m))}>{m}</Chip>
      ))}
    </ChipGroup>
  );
}

