  return (
    <Breadcrumb>
      <BreadcrumbHome href="#" />
      <BreadcrumbItem href="#">정책</BreadcrumbItem>
      <BreadcrumbItem href="#">{POLICY}</BreadcrumbItem>
      <BreadcrumbItem current>{PAGE}</BreadcrumbItem>
    </Breadcrumb>
  );
}

import { Breadcrumb, BreadcrumbHome, BreadcrumbItem } from "@jiran/ds-react";

/* href 도 current 도 없는 항목은 페이지가 없는 상위 단계 — 링크 없이 텍스트로 */
export default function Example() {
  return (
    <Breadcrumb>
      <BreadcrumbHome href="#" />
      <BreadcrumbItem>리포트</BreadcrumbItem>
      <BreadcrumbItem href="#">주간 리포트</BreadcrumbItem>
      <BreadcrumbItem current>2026년 10월 4주차</BreadcrumbItem>
    </Breadcrumb>
  );
}

import { useEffect, useRef, useState } from "react";
import { Breadcrumb, BreadcrumbHome, BreadcrumbItem, BreadcrumbMore } from "@jiran/ds-react";

const HIDDEN = ["정책", "USB 제어"];

export default function Example() {
  const [open, setOpen] = useState(false);
  const nav = useRef<HTMLElement>(null);
  /* … 버튼이 사라지므로 펼친 첫 링크로 포커스를 옮긴다 — 안 옮기면 키보드 사용자가 위치를 잃는다 */
  useEffect(() => {
    if (open) nav.current?.querySelector<HTMLAnchorElement>("li:nth-child(2) a")?.focus();
  }, [open]);
  return (
    <Breadcrumb ref={nav}>
      <BreadcrumbHome href="#" />
      {open
        ? HIDDEN.map((t) => <BreadcrumbItem key={t} href="#">{t}</BreadcrumbItem>)
        : <BreadcrumbMore onClick={() => setOpen(true)} />}
      <BreadcrumbItem href="#">PC-2041</BreadcrumbItem>
      <BreadcrumbItem current>이벤트 #48213</BreadcrumbItem>
    </Breadcrumb>
  );
}

import { Breadcrumb, BreadcrumbHome, BreadcrumbItem, Button, PageHead } from "@jiran/ds-react";

/* Page Header 첫 칸 — 타이틀 바로 위 8px, 한 화면에 하나 */
export default function Example() {
  return (
    <PageHead
      breadcrumb={
        <Breadcrumb>
          <BreadcrumbHome href="#" />
          <BreadcrumbItem href="#">정책</BreadcrumbItem>
          <BreadcrumbItem href="#">USB 제어</BreadcrumbItem>
          <BreadcrumbItem current>외부 저장장치 차단</BreadcrumbItem>
        </Breadcrumb>
      }
      title="외부 저장장치 차단"
      sub="POL-2041 · 전체 그룹"
      actions={<><Button variant="outline" color="assistive">취소</Button><Button>저장</Button></>}
    />
  );
}

