import { Button, ButtonGroup, Empty, Icon } from "@jiran/ds-react";

export default function Example() {
  return (
    <Empty
      icon="shield"
      title="아직 정책이 없습니다"
      style={{ maxWidth: 560 }}
      actions={
        <ButtonGroup>
          <Button variant="outline">템플릿 보기</Button>
          <Button iconLeft={<Icon name="plus" />}>정책 만들기</Button>
        </ButtonGroup>
      }
    >
      템플릿에서 시작하거나 새 정책을 만들어 에이전트에 배포하세요.
    </Empty>
  );
}

import { Button, Empty } from "@jiran/ds-react";

export default function Example() {
  return (
    <Empty icon="search" title="'랜섬웨어 2025' 에 대한 결과가 없습니다" style={{ maxWidth: 560 }} actions={<Button variant="outline" color="assistive">필터 초기화</Button>}>
      검색어를 줄이거나 기간 필터(최근 24시간)를 넓혀 보세요.
    </Empty>
  );
}

import { Button, Empty } from "@jiran/ds-react";

export default function Example() {
  return (
    <Empty compact icon="inbox" title="연결된 알림 채널이 없습니다" style={{ maxWidth: 480 }} actions={<Button variant="outline" color="assistive" size="sm">연결</Button>}>
      Slack 또는 이메일을 연결하세요.
    </Empty>
  );
}

