import { CodeBlock } from "@jiran/ds-react";

const INSTALL = `curl -fsSL https://agent.example.com/install.sh -o install.sh
sudo sh install.sh --group default
sudo systemctl enable --now js-agent`;

export default function Example() {
  return <CodeBlock title="에이전트 설치">{INSTALL}</CodeBlock>;
}

import { CodeBlock } from "@jiran/ds-react";

const LINE = "2026-11-10T09:14:22+09:00 gw-01 kernel: [UFW BLOCK] IN=eth0 OUT= MAC=52:54:00:12:34:56 SRC=203.0.113.24 DST=198.51.100.7 LEN=60 TOS=0x00 PREC=0x00 TTL=52 ID=41021 DF PROTO=TCP SPT=51544 DPT=22 WINDOW=64240 RES=0x00 SYN URGP=0";

export default function Example() {
  return <CodeBlock title="원본 로그" wrap>{LINE}</CodeBlock>;
}

import { InlineCode } from "@jiran/ds-react";

export default function Example() {
  return (
    <p className="t-body-2" style={{ margin: 0 }}>
      설정 파일은 <InlineCode>/etc/js-agent/agent.conf</InlineCode> 에 있습니다. 바꾼 뒤 <InlineCode>systemctl restart js-agent</InlineCode> 를 실행하세요.
    </p>
  );
}

