import { Button, Notice, Stack, StatusItem, StatusList } from "@jiran/ds-react";

export default function Example() {
  return (
    <Stack style={{ maxWidth: 800 }}>
      <Notice tone="danger" title="SIEM 연동 연결 끊김" actions={<><Button size="sm">연동 설정</Button><Button variant="text" size="sm">다시 시도</Button></>}>
        09:12 부터 이벤트 전송이 실패하고 있습니다. 인증 토큰을 확인하세요.
      </Notice>
      <StatusList>
        <StatusItem tone="ok" meta="가동 99.98%">수집 서버</StatusItem>
        <StatusItem tone="ok" meta="rev 2041">정책 배포</StatusItem>
        <StatusItem tone="warn" meta="지연 3분">업데이트 서버</StatusItem>
        <StatusItem tone="danger" meta="09:12 끊김">SIEM 연동</StatusItem>
        <StatusItem tone="info" meta="02:00~04:00">DB 점검</StatusItem>
        <StatusItem tone="ok" meta="842 / 1,000">라이선스</StatusItem>
      </StatusList>
    </Stack>
  );
}

import { Card, CardDesc, CardHead, CardTitle, Progress, Row2, Spinner, Tag } from "@jiran/ds-react";

export default function Example() {
  return (
    <Row2 style={{ maxWidth: 800 }}>
      <Card>
        <CardHead><CardTitle>에이전트 연결</CardTitle><Tag tone="ok">정상</Tag></CardHead>
        <Progress label="온라인" value={1247} max={1284} valueText="1,247 / 1,284" tone="success" />
        <CardDesc>오프라인 37대 · 10분 이상 미체크인 12대</CardDesc>
      </Card>
      <Card>
        <CardHead><CardTitle>진행 중 작업</CardTitle><Spinner size="sm" label="진행 중" /></CardHead>
        <Progress label="정책 rev 2041 배포" value={66} />
        <CardDesc>842 / 1,284대 완료 · 예상 3분</CardDesc>
      </Card>
    </Row2>
  );
}

